INSERT INTO app.chat_messages (id, bot_reply, created_at, is_authenticated, language, user_id, user_message) VALUES (9, 'I''m having trouble answering right now. For any question about your urticaria, please check with your doctor.', '2026-07-05 22:04:08.943398', false, 'en', null, 'What can I do to reduce my hives at night?');
INSERT INTO app.chat_messages (id, bot_reply, created_at, is_authenticated, language, user_id, user_message) VALUES (10, e'Dealing with hives at night can be incredibly frustrating and disrupt your sleep. Here are some general, gentle tips that many people find helpful for managing nighttime itchiness:

*   **Keep your bedroom cool:** Warm temperatures can make itching worse. Try using a fan or air conditioning, and stick to lightweight, breathable blankets.
*   **Wear loose clothing:** Opt for loose-fitting, soft cotton pajamas. Avoid tight elastics or synthetic fabrics that can rub against your skin and trigger hives.
*   **Take a cool shower:** A lukewarm or cool shower or bath before bed can help soothe inflamed skin. Avoid hot water, as heat is a common hive trigger.
*   **Moisturize:** Apply a gentle, fragrance-free moisturizer after your shower to help protect your skin barrier. 
*   **Create a calming routine:** Since stress can sometimes trigger or worsen hives, practicing relaxing activities before bed—like reading or deep breathing—can be beneficial.

*Please remember that I am an AI assistant and not a doctor. Everyone\'s skin is different, so please consult your doctor or a qualified healthcare professional for a proper diagnosis, to discuss safe treatment options, or before making any changes to your medication schedule.*', '2026-07-05 22:19:48.476080', false, 'en', null, 'What can I do to reduce my hives at night?');
INSERT INTO app.chat_messages (id, bot_reply, created_at, is_authenticated, language, user_id, user_message) VALUES (11, 'Je rencontre un problème pour répondre pour le moment. Pour toute question sur ton urticaire, consulte ton médecin.', '2026-07-05 22:20:39.833447', false, 'fr', null, 'Quels aliments eviter ?');
INSERT INTO app.chat_messages (id, bot_reply, created_at, is_authenticated, language, user_id, user_message) VALUES (12, e'Bonjour ! C\'est une question très fréquente. 

En cas d\'urticaire, il faut savoir que les véritables allergies alimentaires sont rarement la cause directe des crises chroniques. Cependant, certains aliments riches en **histamine** (la molécule responsable des démangeaisons) ou qui favorisent sa libération dans le corps peuvent parfois aggraver les poussées chez certaines personnes.

Voici les catégories d\'aliments le plus souvent mentionnées :

*   **Les aliments fermentés ou affinés :** les fromages vieux, la charcuterie, le poisson fumé et certaines boissons alcoolisées (comme le vin rouge).
*   **Certains fruits et légumes :** les tomates, les épinards, les fraises, les agrumes et les bananes très mûres.
*   **Les fruits de mer et les poissons** s\'ils ne sont pas d\'une fraîcheur absolue.
*   **Le chocolat** et le cacao.
*   **Certains additifs et conservateurs** alimentaires.

Plutôt que de supprimer de nombreux aliments par vous-même (ce qui peut entraîner des carences), il est souvent très utile de tenir un journal alimentaire pour noter ce que vous mangez et voir si cela coïncide avec vos poussées d\'urticaire.

*N\'oubliez pas de consulter un médecin, un allergologue ou un nutritionniste pour obtenir un diagnostic précis et des conseils adaptés à votre situation spécifique avant d\'entreprendre un régime d\'éviction.*', '2026-07-05 22:21:36.364253', false, 'fr', null, 'Quels aliments eviter ?');
INSERT INTO app.chat_messages (id, bot_reply, created_at, is_authenticated, language, user_id, user_message) VALUES (13, e'Bonjour ! Je suis l\'assistant UrtiCare. Je suis là pour vous proposer des informations générales et éducatives sur l\'urticaire, ses déclencheurs courants, les soins de la peau et le bien-être en général. 

Comment puis-je vous aider aujourd\'hui ?

*N\'oubliez pas que je ne suis pas médecin. Veuillez toujours consulter un médecin ou un professionnel de la santé qualifié pour obtenir un diagnostic, modifier votre traitement ou pour toute question spécifique à votre situation personnelle.*', '2026-07-05 22:55:53.849172', false, 'fr', null, 'Hello');
INSERT INTO app.chat_messages (id, bot_reply, created_at, is_authenticated, language, user_id, user_message) VALUES (14, e'Bonjour ! Je comprends tout à fait que l\'apparition de papules (qui ressemblent à des plaques d\'urticaire) puisse être inconfortable et que vous cherchiez des solutions pour vous soulager. 

D\'un point de vue général, voici les moyens les plus couramment utilisés pour apaiser et traiter l\'urticaire :

* **Les antihistaminiques :** Ce sont généralement les traitements de première intention. Ils aident à bloquer l\'action de l\'histamine, la substance responsable des démangeaisons et du gonflement.
* **Éviter les déclencheurs :** Si possible, essayez d\'identifier et d\'éviter ce qui a pu provoquer la réaction (chaleur, froid, pression sur la peau, stress, certains aliments ou médicaments).
* **Des gestes apaisants :** Porter des vêtements amples et doux (comme le coton), appliquer des compresses froides sur les zones qui démangent, et éviter de vous gratter pour ne pas aggraver les lésions.

*Attention : Si vous présentez des symptômes plus graves comme des difficultés à respirer, un gonflement du visage, de la langue ou de la gorge, ou des vertiges, il s\'agit d\'une urgence médicale. Dans ce cas, contactez immédiatement les services de secours (le 15 ou le 112).*

Chaque personne réagit différemment et seul un professionnel de santé peut déterminer la cause exacte de vos papules. **N\'oubliez pas de consulter un médecin ou un dermatologue pour obtenir un diagnostic précis, exclure d\'autres causes et recevoir un traitement adapté à votre situation.**', '2026-07-05 22:56:28.871615', false, 'fr', null, 'j''ai des papules est de que il yas un moyen de les soigner ?');
INSERT INTO app.chat_messages (id, bot_reply, created_at, is_authenticated, language, user_id, user_message) VALUES (15, e'Bonjour ! En tant qu\'assistant UrtiCare, je ne suis pas médecin et je ne peux pas vous prescrire, vous conseiller ou vous donner de médicaments. 

Cependant, à titre purement informatif, voici les types de traitements qui sont généralement utilisés et étudiés pour soulager l\'urticaire chronique :

*   **Les antihistaminiques (de deuxième génération) :** Ce sont les traitements de première intention les plus courants. Ils aident à bloquer l\'histamine, la substance chimique libérée par le corps qui cause les plaques et les démangeaisons.
*   **Les traitements de deuxième ligne :** Si les antihistaminiques classiques ne suffisent pas, les médecins peuvent parfois augmenter les doses ou proposer d\'autres options, comme des thérapies ciblées (par injections) ou d\'autres types de médicaments modulateurs du système immunitaire.

Chaque personne réagit différemment et seul un professionnel de la santé peut déterminer la cause de vos symptômes et le traitement qui vous convient le mieux.

*Sachez que si vous présentez des symptômes graves comme des difficultés à respirer, un gonflement du visage, des lèvres ou de la gorge, ou des vertiges, vous devez contacter immédiatement les services d\'urgence (comme le 15 ou le 112).*

**Veuillez consulter un médecin, un dermatologue ou un allergologue pour obtenir un diagnostic précis, une ordonnance adaptée à votre situation ou avant de modifier votre traitement actuel.**', '2026-07-05 23:03:38.355683', false, 'fr', null, 'Vous pouvez me donnez des medicament');
